python3 -c "
# Find smallest cube n^3 that equals a^3 + b^3 in two different ways
# By FLT, n^3 = a^3 + b^3 has no solutions for positive integers.
# But let's verify computationally up to a large range.

results = {}
for a in range(1, 10000):
    for b in range(a+1, 10000):
        s = a**3 + b**3
        # check if s is a perfect cube
        c = round(s ** (1/3))
        if c**3 == s:
            if s not in results:
                results[s] = []
            results[s].append((a, b))

# Find cubes with >= 2 representations
for n3 in sorted(results):
    if len(results[n3]) >= 2:
        print(f'{n3} = {n3}^(1/3)^3, representations: {results[n3]}')
        break
else:
    print('No cube found up to 10000^3 that is sum of two cubes in two ways')
"
